sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var userRecord = new GlideRecord('sys_user');
    var isReadonlyAccessToTaskForm;

    var owningBusinessInTrade = current.trade_id.owning_business;
    var otherBusinessInTrade = current.trade_id.other_business;

    //gs.info("CheckIfGCRelatedUser - owningBusinessInTrade============" + owningBusinessInTrade);
    //gs.info("CheckIfGCRelatedUser - otherBusinessInTrade============" + otherBusinessInTrade);

    if (userRecord.get(gs.getUserID())) {
        var associatedMarketsInUserRecord = userRecord.u_associated_business_markets.toString();

        if (associatedMarketsInUserRecord.indexOf(owningBusinessInTrade) == -1) {
            if ((associatedMarketsInUserRecord.indexOf(otherBusinessInTrade) > -1) && (otherBusinessInTrade.indexOf("GC") > -1)) {
                isReadonlyAccessToTaskForm = true;
            } else {
                isReadonlyAccessToTaskForm = false;
            }
        } else {
            isReadonlyAccessToTaskForm = false;
        }
    } else {
        isReadonlyAccessToTaskForm = false;
    }
    g_scratchpad.isReadonlyAccessToTaskForm = isReadonlyAccessToTaskForm;
})(current, previous);
